KG42.register("clusters-e6e27f58b1ba6de46f18dec9",{"id":"42-data_center_space_time_flexibility::v142-d-K007","paper":"42-data_center_space_time_flexibility","label":"Settlement basis of spatiotemporal clearing results and revenue adequacy candidate.","record":{"cluster_id":"v142-d-K007","label":"Settlement basis of spatiotemporal clearing results and revenue adequacy candidate.","market_meaning":"Clearing quotas and prices enter the payment interpretation for suppliers, transmission, load, and virtual links. The revenue identity under unadjusted nodal prices and the profit definition under adjusted prices are retained separately; at present it cannot be determined that the two bases constitute the same balanced budget account.","mechanism_ids":["v141-a-M06"],"market_types":["DEM"],"process_stages":["clearing","coordination","settlement"],"scope_disposition":"unresolved","scope_explanation":"Limited to the same full-time-domain (3.32) model. Suppliers and transmission use unadjusted prices, load and virtual-link profits use adjusted prices, while the revenue proof uses unadjusted prices; the account linkage when the computing-capacity dual is nonzero is not given.","assembly_status":"partial","boundary_rationale":"Payment rates, cleared metered quantities, and service-provider revenues form settlement rules that can be independently checked; the shared clearing and dual chains provide only interfaces and are not counted again as clearing or equilibrium rules.","chain_bindings":[{"chain_id":"v141-c-R023","ownership":"primary","role":"core","rationale":"Retain the payment basis in the revenue identity and in the profits of each type of participant."},{"chain_id":"v141-c-R021","ownership":"shared","role":"interface","rationale":"Provide only the full-time-domain quotas, nodal balance, and computing-capacity conditions."},{"chain_id":"v141-c-R022","ownership":"shared","role":"interface","rationale":"Provide only the clearing duals and the participant interfaces under fixed prices."}],"connections":[{"connection_id":"v142-d-K007-J01","from_chain_id":"v141-c-R021","to_chain_id":"v141-c-R023","kind":"quantity_interface","from_refs":["v141-c-R021::x::v141-c-R021-x-d","v141-c-R021::x::v141-c-R021-x-p","v141-c-R021::x::v141-c-R021-x-f","v141-c-R021::x::v141-c-R021-x-delta"],"to_refs":["v141-c-R023::x::var_d","v141-c-R023::x::var_p","v141-c-R023::x::var_f","v141-c-R023::x::var_delta"],"evidence_ids":["v141-b-g02-e042","v141-b-g02-e043","v141-b-g03-E15","v141-b-g04-e27"],"rationale":"The same spatiotemporal clearing quota becomes an input to participant payment and revenue measurement."},{"connection_id":"v142-d-K007-J02","from_chain_id":"v141-c-R022","to_chain_id":"v141-c-R023","kind":"quantity_interface","from_refs":["v141-c-R022::x::v141-c-R022-X001","v141-c-R022::x::v141-c-R022-X002"],"to_refs":["v141-c-R023::theta::theta_pi","v141-c-R023::theta::theta_omega"],"evidence_ids":["v141-b-g03-E13","v141-b-g03-E14","v141-b-g03-E15","v141-b-g03-E17"],"rationale":"The clearing nodal dual and the net computing-capacity dual enter the settlement price definition, retaining the roles of dual choice quantities and fixed settlement parameters."},{"connection_id":"v142-d-K007-J03","from_chain_id":"v141-c-R021","to_chain_id":"v141-c-R023","kind":"functional_coupling","from_refs":["v141-c-R021::phi::v141-c-R021-C006"],"to_refs":["v141-c-R023::phi::v141-c-R023-C001"],"evidence_ids":["v141-b-g03-E11","v141-b-g04-e26","v141-b-g04-e27"],"rationale":"The source takes a weighted sum of the spatiotemporal nodal balance using unadjusted nodal prices to obtain the corresponding revenue identity; this derivation does not prove closure of the same account under adjusted-price payments."},{"connection_id":"v142-d-K007-J04","from_chain_id":"v141-c-R022","to_chain_id":"v141-c-R023","kind":"functional_coupling","from_refs":["v141-c-R022::phi::v141-c-R022-C002"],"to_refs":["v141-c-R023::phi::v141-c-R023-C002"],"evidence_ids":["v141-b-g03-E15","v141-b-g03-E17"],"rationale":"The two chains reference the same set of profit definitions and individual subproblems, allowing comparison of fixed-price response and payment terms; the offer-cost deduction term remains part of the profit accounting."}],"object_mappings":[{"mapping_id":"v142-d-K007-O01","kind":"same_quantity","member_refs":["v141-c-R021::x::v141-c-R021-x-d","v141-c-R022::x::v141-c-R022-X004","v141-c-R023::x::var_d"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e043","v141-b-g03-E15","v141-b-g03-E17","v141-b-g04-e27"],"rationale":"The same consumer time quota is used in clearing, fixed-price response, and settlement, retaining the local domain and unit fields."},{"mapping_id":"v142-d-K007-O02","kind":"same_quantity","member_refs":["v141-c-R021::x::v141-c-R021-x-p","v141-c-R022::x::v141-c-R022-X003","v141-c-R023::x::var_p"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e043","v141-b-g03-E15","v141-b-g03-E17","v141-b-g04-e27"],"rationale":"The same supply clearing quantity serves as an input to supplier revenue measurement."},{"mapping_id":"v142-d-K007-O03","kind":"same_quantity","member_refs":["v141-c-R021::x::v141-c-R021-x-f","v141-c-R022::x::v141-c-R022-X007","v141-c-R023::x::var_f"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e042","v141-b-g03-E15","v141-b-g03-E17","v141-b-g04-e27"],"rationale":"The same spatiotemporal directed transmission flow; the unresolved feasible-region discrepancy remains attached to the original object."},{"mapping_id":"v142-d-K007-O04","kind":"same_quantity","member_refs":["v141-c-R021::x::v141-c-R021-x-delta","v141-c-R022::x::v141-c-R022-X005","v141-c-R023::x::var_delta"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e043","v141-b-g03-E15","v141-b-g03-E17","v141-b-g04-e27"],"rationale":"The same virtual load-shifting quota appears in the two accounting bases of profit and revenue; identical quantity does not imply identical rate."},{"mapping_id":"v142-d-K007-O05","kind":"same_quantity","member_refs":["v141-c-R022::x::v141-c-R022-X001","v141-c-R023::theta::theta_pi"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g03-E13","v141-b-g03-E17","v141-b-g04-e27"],"rationale":"The same unadjusted nodal dual price is converted into a settlement input and is not merged with the adjusted-price object."},{"mapping_id":"v142-d-K007-O06","kind":"same_quantity","member_refs":["v141-c-R022::x::v141-c-R022-X002","v141-c-R023::theta::theta_omega"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g03-E14","v141-b-g03-E17","v141-b-g03-E24"],"rationale":"The same net computing-capacity dual serves as a fixed adjustment input in settlement; the original sign uncertainty is retained."},{"mapping_id":"v142-d-K007-O07","kind":"same_quantity","member_refs":["v141-c-R021::theta::v141-c-R021-param-alpha-p","v141-c-R022::theta::v141-c-R022-T001","v141-c-R023::theta::theta_alpha_p"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e042","v141-b-g03-E11","v141-b-g03-E15"],"rationale":"The same supplier time offer is used respectively for welfare cost and supplier profit."},{"mapping_id":"v142-d-K007-O08","kind":"same_quantity","member_refs":["v141-c-R021::theta::v141-c-R021-param-alpha-d","v141-c-R022::theta::v141-c-R022-T003","v141-c-R023::theta::theta_alpha_d"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e042","v141-b-g03-E11","v141-b-g03-E15"],"rationale":"The same demand time offer is used for welfare value and demand profit; the local units remain to be verified."},{"mapping_id":"v142-d-K007-O09","kind":"same_quantity","member_refs":["v141-c-R021::theta::v141-c-R021-param-alpha-f","v141-c-R022::theta::v141-c-R022-T007","v141-c-R023::theta::theta_alpha_f"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e042","v141-b-g03-E11","v141-b-g03-E15"],"rationale":"The same directed transmission service cost enters clearing and profit calculation."},{"mapping_id":"v142-d-K007-O10","kind":"same_quantity","member_refs":["v141-c-R021::theta::v141-c-R021-param-alpha-delta","v141-c-R022::theta::v141-c-R022-T005","v141-c-R023::theta::theta_alpha_delta"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g02-e042","v141-b-g03-E11","v141-b-g03-E15"],"rationale":"The same load-shifting offer is an operating-cost input and must not be conflated with the virtual-link gross revenue rate."}],"gaps":[{"gap_id":"v142-d-K007-G01","category":"math_incomplete","description":"R023-C001 uses unadjusted nodal prices to prove revenue equality, whereas C002 uses adjusted prices to charge load fees and pay virtual links. The account difference and its attribution caused by the computing-capacity dual with respect to net physical load are not set out in the delivered chain; the former identity cannot directly prove that the latter payment basis balances revenue and expenditure.","chain_ids":["v141-c-R021","v141-c-R022","v141-c-R023"],"object_refs":["v141-c-R021::phi::v141-c-R021-C006","v141-c-R023::theta::theta_pi","v141-c-R023::theta::theta_pihat","v141-c-R023::theta::theta_omega","v141-c-R023::phi::v141-c-R023-C001","v141-c-R023::phi::v141-c-R023-C002"],"evidence_ids":["v141-b-g03-E14","v141-b-g03-E15","v141-b-g03-E16","v141-b-g04-e26","v141-b-g04-e27"],"proposal_ids":[],"required_work":"Verify which price is used in actual settlement, clarify the scarcity rent of computing resources and its account attribution, and then have C specify the relationship between the two bases; D does not treat the two prices as the same quantity."},{"gap_id":"v142-d-K007-G02","category":"ambiguous_mapping","description":"R023 records MWh and $/MWh units for general spatiotemporal objects, whereas the supplied general theoretical citation does not specify these units, and R022 also retains unit gaps; a same-quantity interface does not constitute unit verification.","chain_ids":["v141-c-R021","v141-c-R022","v141-c-R023"],"object_refs":["v141-c-R023::x::var_d","v141-c-R023::x::var_delta","v141-c-R023::theta::theta_pi","v141-c-R023::theta::theta_omega"],"evidence_ids":["v141-b-g02-e040","v141-b-g03-E13","v141-b-g03-E15"],"proposal_ids":[],"required_work":"Verify the measurement period and dual units in the general theory, retain the original fields of each chain, and do not backfill with case units."},{"gap_id":"v142-d-K007-G03","category":"unverified_source","description":"On the same page, the intermediate bracketed transcriptions of g04-e27 and g05-e001 in the revenue proof differ, with the latter having an extra demand term. The current interface is provisionally assembled according to g04-e26 and g04-e27, and these citations are not treated as confirmed duplicate evidence.","chain_ids":["v141-c-R023"],"object_refs":["v141-c-R023::phi::v141-c-R023-C001"],"evidence_ids":["v141-b-g04-e26","v141-b-g04-e27","v141-b-g05-e001"],"proposal_ids":[],"required_work":"Independently verify the original page and the intermediate derivation, and clarify the correct scope of each transcription; do not modify the frozen C content in this round."},{"gap_id":"v142-d-K007-G04","category":"upstream_missing","description":"The shared clearing and dual chains still have gaps in the directed flow domain, the hourly feasible set, the lower-bound dual sign, and the complete Lagrangian objective; the settlement interface cannot eliminate these input uncertainties.","chain_ids":["v141-c-R021","v141-c-R022","v141-c-R023"],"object_refs":["v141-c-R021::x::v141-c-R021-x-f","v141-c-R022::x::v141-c-R022-X002","v141-c-R022::x::v141-c-R022-X007","v141-c-R022::phi::v141-c-R022-C002"],"evidence_ids":["v141-b-g02-e042","v141-b-g02-e043","v141-b-g03-E14","v141-b-g03-E17","v141-b-g03-E24"],"proposal_ids":[],"required_work":"Complete the verification of the input domains and dual definitions listed in v142-d-K006, then verify the consistency of the payment rules with the actual clearing results."},{"gap_id":"v142-d-K007-G05","category":"ontology_extension","description":"The proposals for revenue adequacy and computing-capacity attributes have not been approved; the boundary decisions of this cluster cannot replace ontology approval.","chain_ids":["v141-c-R021","v141-c-R023"],"object_refs":["v141-c-R021::V::clearing.social_welfare","v141-c-R023::V::settlement.payment"],"evidence_ids":["v141-b-g03-E13","v141-b-g03-E18","v141-b-g04-e27"],"proposal_ids":["v141-b-g01-p04","v141-b-g03-P2-computing-capacity-constraint"],"required_work":"Manually inspect the proposals and their spatiotemporal scope of application; this round continues to reference only delivered objects."},{"gap_id":"v142-d-K007-G06","category":"unverified_source","description":"The settlement definitions, revenue proof, and shared inputs of this cluster have not passed an independent source audit; the candidate_support status permits only provisional assembly.","chain_ids":["v141-c-R021","v141-c-R022","v141-c-R023"],"object_refs":[],"evidence_ids":["v141-b-g02-e042","v141-b-g02-e043","v141-b-g03-E13","v141-b-g03-E15","v141-b-g03-E17","v141-b-g03-E18","v141-b-g04-e26","v141-b-g04-e27"],"proposal_ids":[],"required_work":"Independently verify the payment basis, proof, units, and input conditions before making a scientific judgment."}]},"rule_refs":["42-data_center_space_time_flexibility::v141-c-R023","42-data_center_space_time_flexibility::v141-c-R021","42-data_center_space_time_flexibility::v141-c-R022"],"unresolved_rule_refs":[],"node_ids":["COMP-8d5245d6855d4191","COMP-c0b1423827b26c77","COMP-ee9696b9d6fa489d","KG40-c62513665ebf8550","KG40-ea70ad747d712a0c"]});
